import type {RenderContext} from "../../RenderContext";
import type {View} from "../../../../../viewer";

import {WebGLRenderBuffer} from "../../webGL";
import {type SDKResult} from "../../../../../../base/core";

import {HDRRenderTarget} from "../hdr/HDRRenderTarget";
import {TonemapPipeline} from "../hdr/TonemapPipeline";
import {FXAAPipeline} from "../fxaa/FXAAPipeline";
import {SMAAPipeline} from "../smaa/SMAAPipeline";
import {BloomPipeline} from "../bloom/BloomPipeline";
import {AtmospherePipeline} from "../atmosphere/AtmospherePipeline";
import {DepthOfFieldPipeline} from "../dof/DepthOfFieldPipeline";
import {ColorGradingPipeline} from "../colorGrading/ColorGradingPipeline";


/**
 * Owns every piece of the HDR substrate and final post-process chain:
 *   - HDR scene render target (RGBA16F).
 *   - LDR intermediate FBO used between tonemap and final AA.
 *   - Bloom, atmosphere, depth of field, color grading, tonemap, FXAA, and SMAA pipelines.
 *
 * Separates two RenderManager concerns from each other:
 *   1. Where the scene draws (canvas vs. HDR target).
 *   2. How the scene texture is composited to the canvas at the end.
 *
 * RenderManager's role shrinks to "set up scene state, render the scene,
 * call composite()". Adding a new post-process step (SSR, color
 * grading, ...) becomes another optional pipeline plugged into this class
 * instead of a diff to RenderManager.
 *
 * Falls back gracefully:
 *   - HDR not supported (extension missing): the whole chain is inert,
 *     scene-binding routes to the default canvas, composite() is a no-op.
 *   - HDR up but a final AA shader fails: renderer still has HDR + tonemap, AA
 *     is silently skipped.
 *   - HDR up but bloom/atmosphere/DOF shader fails: same idea, that effect
 *     is skipped.
 *
 * Each sub-init returns {@link base!core.SDKResult | SDKResult}; failures are localised so the
 * surrounding renderer never aborts a frame because of one shader.
 *
 * @internal
 */
export class PostProcessChain {

  private readonly _renderContext: RenderContext;

  private _hdrTarget: HDRRenderTarget | null = null;
  private _tonemapPipeline: TonemapPipeline | null = null;
  private _fxaaPipeline: FXAAPipeline | null = null;
  private _smaaPipeline: SMAAPipeline | null = null;
  private _bloomPipeline: BloomPipeline | null = null;
  private _atmospherePipeline: AtmospherePipeline | null = null;
  private _depthOfFieldPipeline: DepthOfFieldPipeline | null = null;
  private _colorGradingPipeline: ColorGradingPipeline | null = null;
  private _ldrIntermediate: WebGLRenderBuffer | null = null;

  constructor(renderContext: RenderContext) {
    this._renderContext = renderContext;
  }

  /**
   * Best-effort initialisation of the chain.
   *
   * Always returns `{ok: true}`; individual pipeline failures degrade the
   * chain rather than abort the renderer. Use {@link hasHDR} to query
   * what survived initialisation.
   */
  init(): SDKResult<void> {
    this._initHDR();
    return {ok: true, value: undefined};
  }

  /** True when both halves of the HDR pipeline initialised — implies tonemap is running. */
  hasHDR(): boolean {
    return !!(this._hdrTarget && this._tonemapPipeline);
  }

  /** True when the current View needs the atmosphere post-process. */
  needsAtmosphere(view: View): boolean {
    const atmosphere = view.effects.atmosphere;
    return !!(
      this.hasHDR() &&
      this._atmospherePipeline &&
      atmosphere.applied &&
      atmosphere.possible &&
      atmosphere.intensity > 0 &&
      atmosphere.maxOpacity > 0 &&
      atmosphere.endDistance > atmosphere.startDistance
    );
  }

  /** True when the current View needs the depth-of-field post-process. */
  needsDepthOfField(view: View): boolean {
    const dof = view.effects.depthOfField;
    return !!(
      this.hasHDR() &&
      this._depthOfFieldPipeline &&
      dof.applied &&
      dof.possible &&
      dof.radius > 0 &&
      dof.intensity > 0
    );
  }

  /** True when the current View needs the color-grading post-process. */
  needsColorGrading(view: View): boolean {
    const colorGrading = view.effects.colorGrading;
    return !!(
      this.hasHDR() &&
      this._colorGradingPipeline &&
      colorGrading.applied &&
      colorGrading.possible &&
      (
        colorGrading.brightness !== 0 ||
        colorGrading.contrast !== 1 ||
        colorGrading.saturation !== 1 ||
        colorGrading.gamma !== 1 ||
        colorGrading.temperature !== 0 ||
        colorGrading.tint !== 0
      )
    );
  }

  /** True when the current View needs the renderer to prepare scene depth. */
  needsSceneDepth(view: View): boolean {
    return this.needsAtmosphere(view) || this.needsDepthOfField(view);
  }


  /**
   * Binds the scene-phase target — the HDR FBO at the requested size when
   * HDR is active, the default canvas framebuffer otherwise. Callers do
   * their own viewport / clear after this returns.
   */
  bindSceneTarget(width: number, height: number): void {
    if (this.hasHDR()) {
      this._hdrTarget!.bind(width, height);
    } else {
      const gl = this._renderContext.gl;
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    }
  }

  /**
   * Runs the post-process chain to the canvas.
   *
   * Order: optional bloom (HDR → adds back into HDR), optional atmosphere
   * (HDR + depth → HDR intermediate), optional DOF (HDR + depth → HDR
   * intermediate), optional color grading (HDR → HDR intermediate), tonemap
   * (HDR -> LDR), optional final AA (LDR intermediate -> canvas). When HDR is
   * off, this is a no-op — the scene has already drawn straight to the canvas.
   */
  composite(view: View): void {
    if (!this.hasHDR()) return;

    const rc = this._renderContext;
    const gl = rc.gl;

    // 1. Bloom (optional). Reads HDR, accumulates a blur pyramid, adds it
    //    back into the HDR target. Tonemap downstream sees the bloomed scene.
    if (this._bloomPipeline && view.effects.bloom.applied && view.effects.bloom.possible) {
      const hdrSrc = this._hdrTarget!.getTexture();
      if (hdrSrc) {
        this._bloomPipeline.render({
          hdrSourceTexture: hdrSrc,
          hdrTarget: this._hdrTarget!,
          view
        });
      }
    }

    const hdrTexture = this._hdrTarget!.getTexture();
    this._hdrTarget!.unbind();
    if (!hdrTexture) return;

    let tonemapSource = hdrTexture;

    if (this.needsAtmosphere(view) && rc.sceneDepthTexture) {
      const atmosphereTexture = this._atmospherePipeline!.render({
        colorTexture: tonemapSource,
        depthTexture: rc.sceneDepthTexture,
        view
      });
      if (atmosphereTexture) {
        tonemapSource = atmosphereTexture;
      }
    }

    if (this.needsDepthOfField(view) && rc.sceneDepthTexture) {
      const dofTexture = this._depthOfFieldPipeline!.render({
        colorTexture: tonemapSource,
        depthTexture: rc.sceneDepthTexture,
        view
      });
      if (dofTexture) {
        tonemapSource = dofTexture;
      }
    }

    if (this.needsColorGrading(view)) {
      const colorGradingTexture = this._colorGradingPipeline!.render({
        colorTexture: tonemapSource,
        view
      });
      if (colorGradingTexture) {
        tonemapSource = colorGradingTexture;
      }
    }

    const antiAliasing = view.effects.antiAliasing;
    const wantFXAA = !!(
      this._fxaaPipeline &&
      this._ldrIntermediate &&
      antiAliasing.mode === "fxaa" &&
      antiAliasing.applied &&
      antiAliasing.possible
    );
    const wantSMAA = !!(
      this._smaaPipeline &&
      this._smaaPipeline.ready &&
      this._ldrIntermediate &&
      antiAliasing.mode === "smaa" &&
      antiAliasing.applied &&
      antiAliasing.possible
    );
    const vpW = gl.drawingBufferWidth;
    const vpH = gl.drawingBufferHeight;

    if (wantFXAA || wantSMAA) {
      // 2a. Tonemap -> LDR intermediate, then final AA -> canvas.
      this._ldrIntermediate!.bind();
      gl.viewport(0, 0, vpW, vpH);
      this._tonemapPipeline!.render({hdrTexture: tonemapSource, view});

      const ldrTexture = this._ldrIntermediate!.getTexture();
      this._ldrIntermediate!.unbind();
      gl.viewport(0, 0, vpW, vpH);
      if (ldrTexture) {
        if (wantSMAA) {
          this._smaaPipeline!.render({
            inputTexture: ldrTexture,
            viewportWidth: vpW,
            viewportHeight: vpH
          });
        } else {
          this._fxaaPipeline!.render({
            inputTexture: ldrTexture,
            viewportWidth: vpW,
            viewportHeight: vpH
          });
        }
      }
    } else {
      // 2b. Tonemap straight to the canvas.
      gl.viewport(0, 0, vpW, vpH);
      this._tonemapPipeline!.render({hdrTexture: tonemapSource, view});
    }
  }

  destroy(): void {
    this._hdrTarget?.destroy();
    this._hdrTarget = null;
    this._tonemapPipeline?.destroy();
    this._tonemapPipeline = null;
    this._fxaaPipeline?.destroy();
    this._fxaaPipeline = null;
    this._smaaPipeline?.destroy();
    this._smaaPipeline = null;
    this._bloomPipeline?.destroy();
    this._bloomPipeline = null;
    this._atmospherePipeline?.destroy();
    this._atmospherePipeline = null;
    this._depthOfFieldPipeline?.destroy();
    this._depthOfFieldPipeline = null;
    this._colorGradingPipeline?.destroy();
    this._colorGradingPipeline = null;
    this._ldrIntermediate?.destroy();
    this._ldrIntermediate = null;
  }

  // ------------------------------------------------------------------
  // Private init setup — three layers, each gracefully degrades.
  // ------------------------------------------------------------------

  private _initHDR(): void {
    this._hdrTarget = new HDRRenderTarget(this._renderContext);
    const hdrResult = this._hdrTarget.init();
    if (hdrResult.ok === false) {
      this._hdrTarget.destroy();
      this._hdrTarget = null;
      return;
    }

    this._tonemapPipeline = new TonemapPipeline(this._renderContext);
    const tmResult = this._tonemapPipeline.init();
    if (tmResult.ok === false) {
      this._tonemapPipeline.destroy();
      this._tonemapPipeline = null;
      this._hdrTarget.destroy();
      this._hdrTarget = null;
      return;
    }

    this._initFinalAAIntermediate();
    this._initFXAA();
    this._initSMAA();
    this._initBloom();
    this._initAtmosphere();
    this._initDepthOfField();
    this._initColorGrading();
  }

  private _initFXAA(): void {
    this._fxaaPipeline = new FXAAPipeline(this._renderContext);
    const result = this._fxaaPipeline.init();
    if (result.ok === false) {
      this._fxaaPipeline.destroy();
      this._fxaaPipeline = null;
    }
  }

  private _initSMAA(): void {
    this._smaaPipeline = new SMAAPipeline(this._renderContext);
    const result = this._smaaPipeline.init();
    if (result.ok === false) {
      this._smaaPipeline.destroy();
      this._smaaPipeline = null;
    }
  }

  private _initFinalAAIntermediate(): void {
    this._ldrIntermediate = new WebGLRenderBuffer(
      this._renderContext.webglCanvasElement,
      this._renderContext.gl,
      {
        depthTexture: false,
        // Final AA passes sample at sub-texel offsets along detected edges.
        colorFilter: "linear"
      }
    );
  }

  private _initBloom(): void {
    this._bloomPipeline = new BloomPipeline(this._renderContext);
    const result = this._bloomPipeline.init();
    if (result.ok === false) {
      this._bloomPipeline.destroy();
      this._bloomPipeline = null;
    }
  }

  private _initAtmosphere(): void {
    this._atmospherePipeline = new AtmospherePipeline(this._renderContext);
    const result = this._atmospherePipeline.init();
    if (result.ok === false) {
      this._atmospherePipeline.destroy();
      this._atmospherePipeline = null;
    }
  }

  private _initDepthOfField(): void {
    this._depthOfFieldPipeline = new DepthOfFieldPipeline(this._renderContext);
    const result = this._depthOfFieldPipeline.init();
    if (result.ok === false) {
      this._depthOfFieldPipeline.destroy();
      this._depthOfFieldPipeline = null;
    }
  }

  private _initColorGrading(): void {
    this._colorGradingPipeline = new ColorGradingPipeline(this._renderContext);
    const result = this._colorGradingPipeline.init();
    if (result.ok === false) {
      this._colorGradingPipeline.destroy();
      this._colorGradingPipeline = null;
    }
  }
}
